{
  "sop_id": "SOP-019",
  "title": "Operational Incident Review and Root Cause Analysis",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign to self",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Secure incident record and classify severity",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Collect logs, photographs and witness statements",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Reconstruct timeline",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Identify root cause (5-Why or fishbone)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Assess cost, downtime and safety impact",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Define CAPA with owners and dates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S8",
      "name": "Compile report and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S9",
      "name": "Log DependencyWait while technical findings (D1) or HSE assessment (D2) are outstanding",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge review",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approval",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "always"
    },
    {
      "stage": "HOD",
      "condition": "major incidents only"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Technical findings",
      "item": "Technical findings",
      "parallel_group": "P1"
    },
    {
      "dep_id": "D2",
      "provider": "HSE assessment",
      "item": "HSE assessment",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.85
}
